\set ON_ERROR_STOP on
BEGIN;
SET LOCAL statement_timeout='15s';
DO $$ BEGIN IF current_database() NOT LIKE 'carelink_shadow%' THEN RAISE EXCEPTION 'shadow DB required'; END IF; IF EXISTS(SELECT 1 FROM auth.users WHERE id::text LIKE 'fa800000-%') THEN RAISE EXCEPTION 'fixture collision'; END IF; END $$;
CREATE FUNCTION pg_temp.assert_operation(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'coupon operation: %',label; END IF; END $$;
SELECT pg_temp.assert_operation(NOT has_table_privilege('anon','public.coupon_management_operations','SELECT,INSERT,UPDATE,DELETE') AND NOT has_table_privilege('authenticated','public.coupon_management_operations','SELECT,INSERT,UPDATE,DELETE'),'receipts private');
SELECT pg_temp.assert_operation(NOT has_function_privilege('anon','public.manage_admin_coupon_with_receipt_atomic(uuid,uuid,uuid,uuid,text,jsonb,uuid[])','EXECUTE') AND NOT has_function_privilege('authenticated','public.manage_admin_coupon_with_receipt_atomic(uuid,uuid,uuid,uuid,text,jsonb,uuid[])','EXECUTE'),'gateway service only');
INSERT INTO auth.users(id,email,email_confirmed_at) VALUES('fa800000-0000-4000-8000-000000000001','coupon-operation@example.invalid',now()),('fa800000-0000-4000-8000-000000000002','coupon-operation-other@example.invalid',now());
INSERT INTO public.facility_profiles(id,name,slug,business_type,prefecture,city,address,status) VALUES('fa800001-0000-4000-8000-000000000001','Operation','synthetic-coupon-operation','その他','検証県','検証市','検証住所','draft');
INSERT INTO public.facility_members(user_id,facility_id,role) VALUES('fa800000-0000-4000-8000-000000000001','fa800001-0000-4000-8000-000000000001','owner');
INSERT INTO public.facility_menus(id,facility_id,name,category,price) VALUES('fa800002-0000-4000-8000-000000000001','fa800001-0000-4000-8000-000000000001','A','その他',1000);
CREATE TEMP TABLE coupon_operation_result(value jsonb);GRANT ALL ON coupon_operation_result TO service_role;
SET LOCAL ROLE service_role;
SELECT pg_temp.assert_operation(public.get_admin_coupon_operation('fa800000-0000-4000-8000-000000000001','fa800001-0000-4000-8000-000000000001','fa800004-0000-4000-8000-000000000001','create',NULL)='absent','new operation absent');
INSERT INTO coupon_operation_result SELECT public.manage_admin_coupon_with_receipt_atomic('fa800000-0000-4000-8000-000000000001','fa800001-0000-4000-8000-000000000001',NULL,'fa800004-0000-4000-8000-000000000001','create','{"name":"Once","discount_type":"fixed","discount_value":500}',ARRAY['fa800002-0000-4000-8000-000000000001'::uuid]);
SELECT pg_temp.assert_operation((SELECT (value->>'was_replay')::boolean=false FROM coupon_operation_result),'first save receipt');
SELECT pg_temp.assert_operation((public.manage_admin_coupon_with_receipt_atomic('fa800000-0000-4000-8000-000000000001','fa800001-0000-4000-8000-000000000001',NULL,'fa800004-0000-4000-8000-000000000001','create','{"name":"Once","discount_type":"fixed","discount_value":500}',ARRAY['fa800002-0000-4000-8000-000000000001'::uuid])->>'was_replay')::boolean,'same request replay');
SELECT pg_temp.assert_operation((SELECT count(*)=1 FROM public.coupons WHERE facility_id='fa800001-0000-4000-8000-000000000001'),'replay cannot duplicate coupon');
SELECT pg_temp.assert_operation((SELECT count(*)=1 FROM public.coupon_menus WHERE coupon_id=(SELECT (value->'coupon'->>'id')::uuid FROM coupon_operation_result)),'replay preserves restriction');
SELECT pg_temp.assert_operation(public.get_admin_coupon_operation('fa800000-0000-4000-8000-000000000001','fa800001-0000-4000-8000-000000000001','fa800004-0000-4000-8000-000000000001','create',NULL)='saved','read recovery');
DO $$ BEGIN
 BEGIN PERFORM public.manage_admin_coupon_with_receipt_atomic('fa800000-0000-4000-8000-000000000001','fa800001-0000-4000-8000-000000000001',NULL,'fa800004-0000-4000-8000-000000000001','create','{"name":"Changed","discount_type":"fixed","discount_value":500}',ARRAY[]::uuid[]);RAISE EXCEPTION 'changed request accepted';EXCEPTION WHEN unique_violation THEN NULL;END;
 BEGIN PERFORM public.get_admin_coupon_operation('fa800000-0000-4000-8000-000000000001','fa800001-0000-4000-8000-000000000001','fa800004-0000-4000-8000-000000000001',NULL,NULL);RAISE EXCEPTION 'null kind accepted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 BEGIN PERFORM public.get_admin_coupon_operation('fa800000-0000-4000-8000-000000000002','fa800001-0000-4000-8000-000000000001','fa800004-0000-4000-8000-000000000001','create',NULL);RAISE EXCEPTION 'other actor accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
END $$;
SELECT pg_temp.assert_operation((SELECT name='Once' FROM public.coupons WHERE id=(SELECT (value->'coupon'->>'id')::uuid FROM coupon_operation_result)),'conflict does not modify coupon');
SELECT public.manage_admin_coupon_with_receipt_atomic('fa800000-0000-4000-8000-000000000001','fa800001-0000-4000-8000-000000000001',(SELECT (value->'coupon'->>'id')::uuid FROM coupon_operation_result),'fa800004-0000-4000-8000-000000000004','update','{"name":"Later update"}',NULL);
SELECT public.manage_admin_coupon_with_receipt_atomic('fa800000-0000-4000-8000-000000000001','fa800001-0000-4000-8000-000000000001',NULL,'fa800004-0000-4000-8000-000000000001','create','{"name":"Once","discount_type":"fixed","discount_value":500}',ARRAY['fa800002-0000-4000-8000-000000000001'::uuid]);
SELECT pg_temp.assert_operation((SELECT name='Later update' FROM public.coupons WHERE id=(SELECT (value->'coupon'->>'id')::uuid FROM coupon_operation_result)),'old request replay cannot overwrite newer update');
RESET ROLE;
INSERT INTO public.facility_members(user_id,facility_id,role) VALUES('fa800000-0000-4000-8000-000000000002','fa800001-0000-4000-8000-000000000001','admin');
SET LOCAL ROLE service_role;
DO $$ BEGIN BEGIN PERFORM public.get_admin_coupon_operation('fa800000-0000-4000-8000-000000000002','fa800001-0000-4000-8000-000000000001','fa800004-0000-4000-8000-000000000001','create',NULL);RAISE EXCEPTION 'shared admin reused another actor receipt';EXCEPTION WHEN unique_violation THEN NULL;END;END $$;
SELECT public.manage_admin_coupon_with_receipt_atomic('fa800000-0000-4000-8000-000000000001','fa800001-0000-4000-8000-000000000001',(SELECT (value->'coupon'->>'id')::uuid FROM coupon_operation_result),'fa800004-0000-4000-8000-000000000002','retire');
SELECT pg_temp.assert_operation((public.manage_admin_coupon_with_receipt_atomic('fa800000-0000-4000-8000-000000000001','fa800001-0000-4000-8000-000000000001',(SELECT (value->'coupon'->>'id')::uuid FROM coupon_operation_result),'fa800004-0000-4000-8000-000000000002','retire')->>'was_replay')::boolean,'deletion replay does not become unknown or recreate');
SELECT pg_temp.assert_operation(public.get_admin_coupon_operation('fa800000-0000-4000-8000-000000000001','fa800001-0000-4000-8000-000000000001','fa800004-0000-4000-8000-000000000001','create',NULL)='retired','removed save result is retired');
DO $$ BEGIN BEGIN PERFORM public.manage_admin_coupon_with_receipt_atomic('fa800000-0000-4000-8000-000000000001','fa800001-0000-4000-8000-000000000001',NULL,'fa800004-0000-4000-8000-000000000001','create','{"name":"Once","discount_type":"fixed","discount_value":500}',ARRAY['fa800002-0000-4000-8000-000000000001'::uuid]);RAISE EXCEPTION 'deleted coupon recreated';EXCEPTION WHEN no_data_found THEN NULL;END;END $$;
SELECT pg_temp.assert_operation(NOT EXISTS(SELECT 1 FROM public.coupons WHERE facility_id='fa800001-0000-4000-8000-000000000001'),'tombstone prevents recreation');
RESET ROLE;
CREATE FUNCTION pg_temp.fail_coupon_receipt() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'SYNTHETIC_RECEIPT_FAILURE';END $$;
CREATE TRIGGER synthetic_coupon_receipt_failure BEFORE INSERT ON public.coupon_management_operations FOR EACH ROW EXECUTE FUNCTION pg_temp.fail_coupon_receipt();
SET LOCAL ROLE service_role;
DO $$ BEGIN BEGIN PERFORM public.manage_admin_coupon_with_receipt_atomic('fa800000-0000-4000-8000-000000000001','fa800001-0000-4000-8000-000000000001',NULL,'fa800004-0000-4000-8000-000000000003','create','{"name":"Failed receipt","discount_type":"fixed","discount_value":500}',ARRAY['fa800002-0000-4000-8000-000000000001'::uuid]);RAISE EXCEPTION 'failure missed';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'SYNTHETIC_RECEIPT_FAILURE' THEN RAISE;END IF;END;END $$;
SELECT pg_temp.assert_operation(NOT EXISTS(SELECT 1 FROM public.coupons WHERE facility_id='fa800001-0000-4000-8000-000000000001'),'receipt failure rolls back coupon and mappings');
RESET ROLE;
ROLLBACK;
